/*
 * 文件: flow_rate.bpf.c
 * 功能: 网络流量速率统计。通过挂载内核 IP/UDP 发送路径，统计每条 TCP/UDP 流
 *       的字节数和包数，并聚合到进程级别，可实时计算各进程的网络带宽消耗。
 *       同时复用 kprobe/tcp_retransmit_skb 挂点统计进程重传次数。
 *
 * 挂载的探针类型和内核函数:
 *   - kprobe/ip_queue_xmit      : IP 层 TCP 发包入口，从 sk_buff 取 len 统计流量
 *   - kprobe/udp_sendmsg       : UDP 发包入口，参数直接带 size
 *   - kprobe/tcp_retransmit_skb: TCP 重传入口，用于进程级重传计数
 *
 * 使用的 BPF Map:
 *   - current_sec  : LRU_HASH，按 5 元组 (saddr,daddr,sport,dport,protocol) 统计每条流的字节/包数
 *   - process_stats: LRU_HASH，按 PID 聚合进程级网络画像（comm、tx_bytes、tx_packets、retrans_count）
 *   - cfg_iface    : HASH，key=0，用户态可预配置网卡 ifindex 过滤（0 表示不过滤）
 *
 * 用户态对应的 Monitor 类: FlowRateMonitor / NetworkQualityAssessor
 */

#define __TARGET_ARCH_arm64
#include "vmlinux.h"
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_core_read.h>
#include <bpf/bpf_tracing.h>
#include <bpf/bpf_endian.h>
#ifndef AF_INET
#define AF_INET 2
#endif

char LICENSE[] SEC("license") = "GPL";

// =============================================================================
// 数据结构定义
// =============================================================================

/*
 * 流标识 Key（5 元组）
 * 用 __attribute__((packed)) 消除编译器可能插入的 padding，
 * 保证作为 Map Key 时的唯一性和可哈希性
 */
struct conn_key {
    __u32 saddr;      // 源 IP（网络序，来自 skc_rcv_saddr）
    __u32 daddr;      // 目的 IP（网络序，来自 skc_daddr）
    __u16 sport;      // 源端口（网络序，bpf_htons(skc_num)）
    __u16 dport;      // 目的端口（网络序，skc_dport 直接存网络序）
    __u8  protocol;   // IP 协议号：6=TCP, 17=UDP
} __attribute__((packed));

/*
 * 单条流的数据统计（存储在 current_sec Map 的 Value）
 */
struct flow_data {
    __u64 bytes;      // 累计发送字节数
    __u64 packets;    // 累计发送包数
    __u32 pid;        // 最近一次发送此流数据的进程 PID
};

/*
 * 进程级网络画像（存储在 process_stats Map 中）
 * 用户态可通过此 Map 识别哪些进程正在消耗带宽
 */
struct process_net_stats {
    char  comm[16];        // 进程名（Linux 内核限制 16 字节，含结尾 \0）
    __u64 tx_bytes;        // 该进程所有 TCP+UDP 流的累计发送字节数
    __u64 tx_packets;      // 累计发送包数
    __u64 retrans_count;   // TCP 重传次数（由 trace_tcp_retransmit 挂点累计）
};

// =============================================================================
// BPF Map 定义
// =============================================================================

/*
 * Map: current_sec
 * 类型: BPF_MAP_TYPE_LRU_HASH（LRU 淘汰，65536 条目）
 * Key:  struct conn_key（5 元组）
 * Value: struct flow_data（字节数/包数/PID）
 * 最大条目数: 65536（高并发连接场景下足够容纳活跃流，LRU 自动淘汰冷门流）
 * 用途: 存储当前正在发送的每条流的累计统计。
 *       LRU_HASH 的好处：1) 自动内存管理，不会因为某条流发完就忘记删
 *                       2) 比 PERCPU_ARRAY 灵活，支持动态 5 元组
 * 命名 "current_sec" 暗示：用户态可以每秒轮询后清空（或直接替换为新窗口）
 */
struct {
    __uint(type, BPF_MAP_TYPE_LRU_HASH);
    __uint(max_entries, 65536);
    __type(key, struct conn_key);
    __type(value, struct flow_data);
} current_sec SEC(".maps");

/*
 * Map: process_stats
 * 类型: BPF_MAP_TYPE_LRU_HASH
 * Key:  __u32 = 进程 TGID（bpf_get_current_pid_tgid() 高 32 位，即进程 PID；
 *       低 32 位是线程 TID——按 TID 分桶会把多线程进程拆成多行）
 * Value: struct process_net_stats（进程级画像）
 * 最大条目数: 65536
 * 用途: 按进程聚合所有网络流量。account_flow() 每次调用时同时更新
 *       current_sec（流级）和 process_stats（进程级）两张 Map。
 *       进程第一次出现时用 bpf_get_current_comm() 抓取 16 字节进程名。
 */
struct {
    __uint(type, BPF_MAP_TYPE_LRU_HASH);
    __uint(max_entries, 65536);
    __type(key, __u32);
    __type(value, struct process_net_stats);
} process_stats SEC(".maps");

/*
 * Map: cfg_iface
 * 类型: BPF_MAP_TYPE_HASH（单条目配置 Map）
 * Key:  __u32，固定值 0
 * Value: __u32，网卡 ifindex（0 表示不限制，所有接口都统计）
 * 最大条目数: 1
 * 用途: 用户态可预加载，实现"只统计指定网卡"的能力。
 *       例如只统计 Wi-Fi 接口（wlan0 的 ifindex 通常较小），
 *       排除 loopback (lo) 和 docker (docker0) 等虚拟接口。
 */
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1);
    __type(key, __u32);     // 固定 key=0
    __type(value, __u32);   // ifindex
} cfg_iface SEC(".maps");

// =============================================================================
// 辅助函数
// =============================================================================

/*
 * 判断 sk_buff 所属网卡是否在用户态配置的白名单内
 * @skb_ifindex sk_buff->dev->ifindex，由调用方提取好传入
 * 返回: true=允许统计，false=跳过
 * 逻辑：cfg_iface 里没配置 → 全部放行；cfg_iface=0 → 全部放行；
 *       cfg_iface=N(非 0) → 只允许 ifindex==N 的包
 */
static __always_inline bool iface_allowed(__u32 skb_ifindex)
{
    __u32 key = 0;
    __u32 *want = bpf_map_lookup_elem(&cfg_iface, &key);
    if (!want) return true;  // 未配置则放行
    if (*want == 0) return true;
    return skb_ifindex == *want;
}

/*
 * 从 struct sock 构造 5 元组 conn_key
 * 仅处理 AF_INET（IPv4），IPv6 可扩展 AF_INET6 分支
 * @proto IP 协议号，由调用方传入（6=TCP，17=UDP）
 * 返回: 0=成功，-1=非 IPv4 家族
 */
static __always_inline int fill_key_from_sock(struct sock *sk, __u8 proto, struct conn_key *k)
{
    __u16 family = BPF_CORE_READ(sk, __sk_common.skc_family);
    if (family != AF_INET)
        return -1;

    // skc_rcv_saddr / skc_daddr：内核中存储的 IP 地址（网络字节序）
    k->saddr = BPF_CORE_READ(sk, __sk_common.skc_rcv_saddr);
    k->daddr = BPF_CORE_READ(sk, __sk_common.skc_daddr);
    // skc_num 是主机序（小端），端口号在网络传输时是网络序，故转一下
    __u16 sport_host = BPF_CORE_READ(sk, __sk_common.skc_num);
    k->sport = bpf_htons(sport_host);
    // skc_dport 内核已经存网络序，直接使用
    k->dport = BPF_CORE_READ(sk, __sk_common.skc_dport);
    k->protocol = proto;
    return 0;
}

/*
 * 核心统计函数：同时更新"流级 Map"和"进程级 Map"
 * @k         5 元组 Key（已填好）
 * @add_bytes 本次发送的字节数（来自 skb->len 或 msghdr->size）
 *
 * 流程：
 *   1. 在 current_sec (LRU_HASH) 中查找或创建 flow_data
 *   2. 原子累加 bytes 和 packets（同一 CPU 上 kprobe 可以并发，用 __sync_fetch_and_add）
 *   3. 更新 process_stats (LRU_HASH)：用 bpf_get_current_pid_tgid() 取 PID 作为 Key
 *   4. 进程首次出现时调用 bpf_get_current_comm() 抓取 16 字节进程名
 */
static __always_inline void account_flow(struct conn_key *k, __u64 add_bytes)
{
    // === 流级统计 ===
    struct flow_data *v = bpf_map_lookup_elem(&current_sec, k);
    if (!v) {
        // 首次出现此 5 元组：创建初始化记录
        struct flow_data init = {0};
        init.bytes = add_bytes;
        init.packets = 1;
        // bpf_get_current_pid_tgid() 返回 (TGID << 32) | TID：
        //   高 32 位 = 进程 TGID（即 PID，用户态期望的进程标识）
        //   低 32 位 = 线程 TID（按它分桶会把多线程进程拆成多行，
        //               云端 top_processes 会拿到线程号冒充进程号）
        // 取进程标识必须 >> 32（对照 tcp_retransmit.bpf.c 同一 helper 的用法）
        init.pid = (__u32)(bpf_get_current_pid_tgid() >> 32);
        bpf_map_update_elem(&current_sec, k, &init, 0);  // BPF_NOEXIST：只创建不覆盖
    } else {
        // 已存在：原子累加
        __sync_fetch_and_add(&v->bytes, add_bytes);
        __sync_fetch_and_add(&v->packets, 1);
        v->pid = (__u32)(bpf_get_current_pid_tgid() >> 32);
    }

    // === 进程级统计 ===
    // Key 取 TGID（进程 PID），多线程进程聚合为一行
    __u32 pid = (__u32)(bpf_get_current_pid_tgid() >> 32);
    struct process_net_stats *ps = bpf_map_lookup_elem(&process_stats, &pid);
    if (!ps) {
        struct process_net_stats init = {};
        // bpf_get_current_comm：BPF 辅助函数 #159，从 task_struct->comm 复制进程名
        // 大小固定 16 字节，与内核 TASK_COMM_LEN 对齐
        bpf_get_current_comm(init.comm, sizeof(init.comm));
        init.tx_bytes = add_bytes;
        init.tx_packets = 1;
        bpf_map_update_elem(&process_stats, &pid, &init, 0);
    } else {
        __sync_fetch_and_add(&ps->tx_bytes, add_bytes);
        __sync_fetch_and_add(&ps->tx_packets, 1);
    }
}

// =============================================================================
// BPF 入口函数 1: TCP 重传计数（进程级）
// =============================================================================

/*
 * 函数: trace_tcp_retransmit（重传专用）
 * 挂点: SEC("kprobe/tcp_retransmit_skb")
 * 触发时机: 每当 TCP 检测到丢包并重新发送 sk_buff 时。
 *           内核函数签名: int tcp_retransmit_skb(struct sock *sk, struct sk_buff *skb, int segs)
 * 主要逻辑: 以当前 PID 为 Key，在 process_stats 中累加 retrans_count。
 *           与 tcp_retransmit.bpf.c 的区别：那个按"连接"维度统计，
 *           这里按"进程"维度统计（一个进程可能有多个 TCP 连接）。
 * 写入的 Map: process_stats（累加 retrans_count）
 */
SEC("kprobe/tcp_retransmit_skb")
int trace_tcp_retransmit(struct pt_regs *ctx)
{
    // 取进程 PID（>> 32 取 TGID；& 0xffffffff 取到的是线程 TID，与
    // account_flow 的 key 语义必须一致，否则重传记到别的 key 上）
    __u32 pid = (__u32)(bpf_get_current_pid_tgid() >> 32);
    struct process_net_stats *ps = bpf_map_lookup_elem(&process_stats, &pid);
    if (!ps) {
        struct process_net_stats init = {};
        bpf_get_current_comm(init.comm, sizeof(init.comm));
        init.retrans_count = 1;
        bpf_map_update_elem(&process_stats, &pid, &init, 0);
    } else {
        __sync_fetch_and_add(&ps->retrans_count, 1);
    }
    return 0;
}

// =============================================================================
// BPF 入口函数 2: IP 层 TCP 发包入口
// =============================================================================

/*
 * 函数: tcp_transmit_entry
 * 挂点: SEC("kprobe/ip_queue_xmit")
 * 触发时机: 每当 IP 层准备发送一个 sk_buff 时。
 *           内核函数签名: int ip_queue_xmit(struct sock *sk, struct sk_buff *skb, ...)
 *           此函数是 TCP 发包的必经之路（UDP 走 ip_send_skb，但我们用 udp_sendmsg 挂点更精确）。
 * 主要逻辑:
 *   1. 从 PT_REGS_PARM1/2 取出 struct sock 和 struct sk_buff
 *   2. 从 skb->dev->ifindex 提取网卡号，调用 iface_allowed() 判断是否在白名单内
 *   3. fill_key_from_sock(sk, 6, &k) 构造 TCP 5 元组
 *   4. BPF_CORE_READ(skb, len) 获取 IP 包长度（不含链路层头）
 *   5. account_flow() 同时更新流级和进程级 Map
 * 写入的 Map: current_sec + process_stats
 *
 * sk_buff 结构说明:
 *   skb->dev    : 指向发送/接收网卡的 struct net_device*
 *   skb->dev->ifindex : 网卡在内核中的唯一编号（lo=1, eth0=2, wlan0=3...）
 *   skb->len    : skb 中线性数据区的长度（不含非线性 fragment 的 data_len）
 */
SEC("kprobe/ip_queue_xmit")
int tcp_transmit_entry(struct pt_regs *ctx)
{
    struct sock *sk = (struct sock *)PT_REGS_PARM1(ctx);
    struct sk_buff *skb = (struct sk_buff *)PT_REGS_PARM2(ctx);
    if (!sk || !skb) return 0;

    // === 网卡过滤 ===
    // BPF_CORE_READ(skb, dev) 读 sk_buff 的 dev 成员（struct net_device *）
    struct net_device *dev = BPF_CORE_READ(skb, dev);
    __u32 ifindex = dev ? BPF_CORE_READ(dev, ifindex) : 0;
    if (!iface_allowed(ifindex)) return 0;  // 不在白名单内则跳过

    // 构造 TCP 5 元组（6=IPPROTO_TCP）
    struct conn_key k = {};
    if (fill_key_from_sock(sk, 6 /*TCP*/, &k) < 0)
        return 0;

    // BPF_CORE_READ(skb, len)：sk_buff 的 len 成员，
    // 是 IP 层视角的包长度（从 IP 头开始算），不含以太网头
    __u32 len = BPF_CORE_READ(skb, len);
    account_flow(&k, len);
    return 0;
}

// =============================================================================
// BPF 入口函数 3: UDP 发包入口
// =============================================================================

/*
 * 函数: udp_send_entry
 * 挂点: SEC("kprobe/udp_sendmsg")
 * 触发时机: 每当 UDP socket 发送数据时。
 *           内核函数签名: int udp_sendmsg(struct sock *sk, struct msghdr *msg, size_t len)
 * 主要逻辑:
 *   1. 从 PT_REGS_PARM3 直接拿到 len（用户态本次 send 的字节数）
 *   2. fill_key_from_sock(sk, 17, &k) 构造 UDP 5 元组（17=IPPROTO_UDP）
 *   3. account_flow() 更新两张 Map
 * 写入的 Map: current_sec + process_stats
 *
 * 为什么 UDP 不做 ifindex 过滤？
 *   UDP 在 udp_sendmsg 时 skb 还没构造，无法提前知道会走哪块网卡。
 *   接口过滤对 UDP 兼容性差（旧内核字段名不同），此处简化为不做过滤。
 */
SEC("kprobe/udp_sendmsg")
int udp_send_entry(struct pt_regs *ctx)
{
    struct sock *sk = (struct sock *)PT_REGS_PARM1(ctx);
    // PT_REGS_PARM3 对应 msghdr 参数后面的 size_t len
    unsigned long len = (unsigned long)PT_REGS_PARM3(ctx);
    if (!sk) return 0;

    // UDP 无 skb，不做接口过滤，仍统计总量
    struct conn_key k = {};
    if (fill_key_from_sock(sk, 17 /*UDP*/, &k) < 0)
        return 0;

    account_flow(&k, (__u64)len);
    return 0;
}

/*
 * 文件: tcp_retransmit.bpf.c
 * 功能: TCP 重传追踪。通过挂载 TCP 内核层的 kprobe，按"连接"维度统计
 *       TCP 重传事件和分段数，用于高效计算 TCP 丢包率：
 *         丢包率 = total_retrans / total_segs
 *       替代传统方案（周期性 cat /proc/net/netstat 或 netlink dump，开销大）。
 *
 * 挂载的探针类型和内核函数:
 *   - kprobe/tcp_retransmit_skb : TCP 重传发生时触发（主动丢包告警）
 *   - kprobe/tcp_sendmsg       : TCP 数据发送时触发（估算发送总段数，用作丢包率分母）
 *
 * 使用的 BPF Map:
 *   - retrans_events : LRU_HASH，key=TCP 4 元组，存储最近一次重传事件详情（时间戳/PID/计数）
 *   - retrans_stats  : LRU_HASH，key=TCP 4 元组，存储连接级累计统计（total_retrans / total_segs）
 *
 * 用户态对应的 Monitor 类: TcpRetransmitMonitor（/ net_tcp_monitor）
 *
 * 与 flow_rate.bpf.c 的重传挂点对比：
 *   本文件：按"连接"维度（4 元组）统计重传，适合定位"哪条 TCP 连接在丢包"
 *   flow_rate.bpf.c：按"进程"维度统计重传，适合定位"哪个进程的网络在抖动"
 */

#define __TARGET_ARCH_arm64
#include "vmlinux.h"
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_core_read.h>
#include <bpf/bpf_tracing.h>
#include <bpf/bpf_endian.h>
#ifndef AF_INET
#define AF_INET 2
#endif

char LICENSE[] SEC("license") = "GPL";

// =============================================================================
// 数据结构定义
// =============================================================================

/*
 * TCP 连接标识 Key（4 元组，仅支持 IPv4）
 * 与 http_latency.bpf.c 的 tcp_conn_key 不同，这里用 packed 消除 padding，
 * 且只覆盖 IPv4（足够覆盖绝大多数移动网络场景）
 */
struct tcp_conn_key {
    __u32 saddr;   // 源 IP（网络序）
    __u32 daddr;   // 目的 IP（网络序）
    __u16 sport;   // 源端口（网络序，bpf_htons(skc_num)）
    __u16 dport;   // 目的端口（网络序，skc_dport 直接存储）
} __attribute__((packed));

/*
 * 重传事件详情（存储在 retrans_events Map 的 Value）
 * LRU Hash 自动只保留最近的事件，用户态轮询消费后可删除，
 * 但即使不删，LRU 也会淘汰最久的条目
 */
struct tcp_retrans_event {
    __u32 pid;          // 触发重传的进程 PID（bpf_get_current_pid_tgid 高 32 位）
    __u32 tgid;         // 线程组 ID（通常与 PID 相同）
    __u64 timestamp_ns; // 重传发生的时间戳（bpf_ktime_get_ns，单调时钟）
    __u32 segs_out;     // 累计已发送段数（预留字段，暂未填充，内核 tcp_sock 中有 tcpi_segs_out）
    __u32 segs_retrans; // 累计重传段数（预留字段）
    __u32 sstate;       // TCP socket 状态（预留字段，可从 sk->__sk_common.skc_state 读取）
};

/*
 * 连接级重传统计（存储在 retrans_stats Map 的 Value）
 * 用户态用以下公式计算丢包率:
 *   丢包率 = total_retrans / max(total_segs, 1)
 *   若某条连接 total_segs=0（只有重传，没有新发送），则分母取 1
 */
struct tcp_retrans_stats {
    __u64 total_retrans; // 该连接累计重传次数（每次 tcp_retransmit_skb +1）
    __u64 total_segs;    // 该连接累计估算发送段数（每次 tcp_sendmsg +ceil(size/1460)）
    __u32 last_state;    // 最近一次观测到的 TCP 状态（预留字段）
};

// =============================================================================
// BPF Map 定义
// =============================================================================

/*
 * Map: retrans_events
 * 类型: BPF_MAP_TYPE_LRU_HASH
 * Key:  struct tcp_conn_key（4 元组）
 * Value: struct tcp_retrans_event（事件详情）
 * 最大条目数: 1024（LRU 保证最多保留 1024 个活跃连接的最近一次重传）
 * 用途: 用户态轮询此 Map 可以获得每条连接最后一次重传的时间戳，
 *       用于实时告警（如重传在 1 秒内频繁发生）。
 *       之所以用 LRU_HASH 而不是 PERF_EVENT_ARRAY，
 *       是因为我们需要"按连接 Key 聚合"，而不是流式消费所有事件。
 */
struct {
    __uint(type, BPF_MAP_TYPE_LRU_HASH);
    __uint(max_entries, 1024);
    __type(key, struct tcp_conn_key);
    __type(value, struct tcp_retrans_event);
} retrans_events SEC(".maps");

/*
 * Map: retrans_stats
 * 类型: BPF_MAP_TYPE_LRU_HASH
 * Key:  struct tcp_conn_key（4 元组）
 * Value: struct tcp_retrans_stats（累计统计）
 * 最大条目数: 65536（高并发下足够，LRU 自动淘汰冷门连接）
 * 用途: 存储每条 TCP 连接的累计重传统计。
 *       tcp_retransmit_skb 入口 → total_retrans +1
 *       tcp_sendmsg 入口 → total_segs +ceil(size/1460)
 *       用户态定期读取后重置（或依赖 LRU 自然淘汰）。
 */
struct {
    __uint(type, BPF_MAP_TYPE_LRU_HASH);
    __uint(max_entries, 65536);
    __type(key, struct tcp_conn_key);
    __type(value, struct tcp_retrans_stats);
} retrans_stats SEC(".maps");

/*
 * Map: retrans_self_pid
 * 服务端自身 PID。用于排除**主动探测**连接的 TCP 重传。
 *
 * 为什么这里必须排除：本探针的 total_retrans / total_segs 直接喂给
 * Reliability SLE —— 一个 blocking 的 Core SLE。主动探测目标是
 * "应稳定可达"的，若其重传进入本窗口，会人为改变丢包率并影响
 * Overall 判决，同时破坏 Active/Passive 证据边界。
 *
 * ── 为什么只做 PID 过滤、不做 socket cookie 桥接 ──
 *
 * 曾尝试照搬 dns_monitor 的 cookie 方案（sendmsg 侧登记 cookie、
 * retransmit 侧按 cookie 排除），在开发板上**加载失败**：
 *
 *   libbpf: prog 'trace_tcp_retransmit': failed to load: -22
 *   unknown func bpf_get_socket_cookie#46
 *
 * 原因：kprobe/tcp_retransmit_skb 的上下文不被该内核（5.15.147）允许
 * 调用 bpf_get_socket_cookie；而 dns_monitor 的挂点在 skb 路径上，
 * 上下文不同，故它能用而这里不能。
 *
 * 因此本探针的覆盖是**有方向的**：
 *   - sendmsg（分母）：在调用方进程上下文，PID 可靠 → 完全排除
 *   - retransmit（分子）：由进程上下文触发时 PID 有效 → 排除；
 *     由**重传定时器**在 softirq 触发时 PID 不可用 → 漏过
 *
 * 这个残余方向已知且有界：它只会**少算**分子（放宽），不会因分母被
 * 单侧削减而**抬高**丢包率造成假 BAD。原实现两侧都不排除才是真正
 * 危险的不对称。残余漏过由真机验收的实际数值观察兜底。
 */
struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, __u32);
} retrans_self_pid SEC(".maps");

// =============================================================================
// 辅助函数
// =============================================================================

static __always_inline bool is_self_pid(void)
{
    __u32 k = 0;
    __u32 *self = bpf_map_lookup_elem(&retrans_self_pid, &k);
    if (!self || *self == 0)
        return false;   // 未设置时不误杀
    return ((__u32)(bpf_get_current_pid_tgid() >> 32)) == *self;
}

/*
 * 从 struct sock 构造 TCP 4 元组 Key
 * 仅处理 AF_INET（IPv4）
 * @return 0=成功，-1=非 IPv4（跳过）
 */
static __always_inline int fill_conn_key(struct sock *sk, struct tcp_conn_key *k)
{
    __u16 family = BPF_CORE_READ(sk, __sk_common.skc_family);
    if (family != AF_INET)
        return -1;

    // skc_rcv_saddr / skc_daddr 是内核存 IP 的字段名
    k->saddr = BPF_CORE_READ(sk, __sk_common.skc_rcv_saddr);
    k->daddr = BPF_CORE_READ(sk, __sk_common.skc_daddr);
    // skc_num 存主机序端口，用 bpf_htons 转网络序（大端），保证跨架构 Key 一致
    __u16 sport_host = BPF_CORE_READ(sk, __sk_common.skc_num);
    k->sport = bpf_htons(sport_host);
    // skc_dport 内核直接存网络序，不需要转换
    k->dport = BPF_CORE_READ(sk, __sk_common.skc_dport);
    return 0;
}

// =============================================================================
// BPF 入口函数 1: TCP 重传事件
// =============================================================================

/*
 * 函数: trace_tcp_retransmit
 * 挂点: SEC("kprobe/tcp_retransmit_skb")
 * 触发时机: 每当 TCP 内核决定重传一个 sk_buff 时。
 *           内核函数签名: int tcp_retransmit_skb(struct sock *sk, struct sk_buff *skb, int segs)
 * 主要逻辑:
 *   1. PT_REGS_PARM1 取出 struct sock *sk
 *   2. fill_conn_key(sk, &key) 构造 TCP 4 元组
 *   3. bpf_ktime_get_ns() 取单调时钟时间戳
 *   4. bpf_get_current_pid_tgid() 取触发重传的进程 PID/TGID
 *   5. 在 retrans_stats 中 total_retrans +1（原子累加）
 *   6. 在 retrans_events 中写入完整事件详情
 * 写入的 Map:
 *   - retrans_stats（total_retrans +1）
 *   - retrans_events（写入完整事件）
 */
SEC("kprobe/tcp_retransmit_skb")
int trace_tcp_retransmit(struct pt_regs *ctx)
{
    // PT_REGS_PARM1(ctx) 提取第一个参数 struct sock *sk
    struct sock *sk = (struct sock *)PT_REGS_PARM1(ctx);
    if (!sk)
        return 0;

    // === 排除服务端自身（主动探测）的连接 ===
    // 仅 PID 判据：本挂点不允许调用 bpf_get_socket_cookie
    // （unknown func #46，见 retrans_self_pid 的说明）。
    if (is_self_pid())
        return 0;

    // 构造 TCP 4 元组 Key
    struct tcp_conn_key key = {};
    if (fill_conn_key(sk, &key) < 0)
        return 0;

    // bpf_ktime_get_ns()：内核单调时钟，基于 sched_clock()
    __u64 now = bpf_ktime_get_ns();
    // bpf_get_current_pid_tgid()：返回 (PID << 32) | TID
    // 右移 32 位拿到 PID，& 0xffffffff 拿 TID
    __u32 pid_tgid = (__u32)(bpf_get_current_pid_tgid() >> 32);

    // === 更新连接级累计统计 ===
    struct tcp_retrans_stats *stat = bpf_map_lookup_elem(&retrans_stats, &key);
    if (stat) {
        // __sync_fetch_and_add：原子内置函数，编译为 lock add 指令
        // 保证多核并发触发时不会丢计数
        __sync_fetch_and_add(&stat->total_retrans, 1);
        stat->last_state = 0;  // 预留：可从 skc_state 读真实 TCP 状态
    } else {
        // 第一次看到此连接：创建初始化记录
        struct tcp_retrans_stats init = {0};
        init.total_retrans = 1;
        init.total_segs = 0;
        bpf_map_update_elem(&retrans_stats, &key, &init, BPF_ANY);
    }

    // === 记录最近一次重传事件详情 ===
    struct tcp_retrans_event event = {0};
    event.pid = pid_tgid;
    event.tgid = bpf_get_current_pid_tgid() >> 32;  // 与 pid 相同（同一进程）
    event.timestamp_ns = now;
    // segs_out / segs_retrans / sstate 是预留字段，
    // 可扩展读取 tcp_sock->tcpi_segs_out 等内核内部计数器
    event.segs_out = 0;
    event.segs_retrans = 1;  // 本次就是 1 个段的重传
    bpf_map_update_elem(&retrans_events, &key, &event, BPF_ANY);

    return 0;
}

// =============================================================================
// BPF 入口函数 2: TCP 发送量统计（用作丢包率分母）
// =============================================================================

/*
 * 函数: trace_tcp_sendmsg
 * 挂点: SEC("kprobe/tcp_sendmsg")
 * 触发时机: 每当 TCP socket 发送数据时。
 *           内核函数签名: int tcp_sendmsg(struct sock *sk, struct msghdr *msg, size_t size)
 * 主要逻辑:
 *   1. PT_REGS_PARM1/3 取 struct sock *sk 和 size
 *   2. fill_conn_key(sk, &key) 构造 TCP 4 元组
 *   3. 用 MSS≈1460 估算本次发送会产生多少个 TCP 段：ceil(size / 1460)
 *   4. 在 retrans_stats 中累加 total_segs
 * 写入的 Map: retrans_stats（total_segs +估算值）
 *
 * 丢包率计算公式:
 *   loss_rate = total_retrans / max(total_segs, 1)
 *
 * 为什么用估算而不是精确值？
 *   精确段数需要读 tcp_sock->snd_nxt / snd_una 差值，BPF_CORE_READ 对 tcp_sock
 *   的嵌套结构偏移不稳定，MSS 近似足够用于统计场景。
 */
SEC("kprobe/tcp_sendmsg")
int trace_tcp_sendmsg(struct pt_regs *ctx)
{
    struct sock *sk = (struct sock *)PT_REGS_PARM1(ctx);
    unsigned long size = (unsigned long)PT_REGS_PARM3(ctx);
    if (!sk || size == 0)
        return 0;

    // === 排除服务端自身（主动探测）的发送 ===
    // sendmsg 在调用方进程上下文，PID 可靠。
    // 与 retransmit 侧使用同一判据（本挂点同样不允许
    // bpf_get_socket_cookie）。
    if (is_self_pid())
        return 0;

    struct tcp_conn_key key = {};
    if (fill_conn_key(sk, &key) < 0)
        return 0;

    // MSS 近似值 1460（以太网 MTU 1500 - IP头20 - TCP头20）
    // ceil(size / 1460) = (size + 1459) / 1460
    // 任何 size > 0 至少产生 1 个段
    __u64 segs = (size + 1459) / 1460;
    if (segs == 0) segs = 1;

    // 与 trace_tcp_retransmit 更新同一张 Map（retrans_stats），
    // 原子累加 total_segs，与 total_retrans 配合计算丢包率
    struct tcp_retrans_stats *stat = bpf_map_lookup_elem(&retrans_stats, &key);
    if (stat) {
        __sync_fetch_and_add(&stat->total_segs, segs);
    } else {
        struct tcp_retrans_stats init = {0};
        init.total_retrans = 0;
        init.total_segs = segs;
        bpf_map_update_elem(&retrans_stats, &key, &init, BPF_ANY);
    }

    return 0;
}

/*
 * 文件: http_latency.bpf.c
 * 功能: HTTP 请求级延迟追踪。通过挂载 TCP 发送/接收路径的 kprobe，
 *       从用户态 msghdr.msg_iter.iov 中提取明文 HTTP 请求/响应首部，
 *       计算 TTFB（Time To First Byte，首字节延迟），
 *       用于区分"应用慢"（服务器处理延迟长）vs "网络慢"（传输延迟长）。
 *
 * 挂载的探针类型和内核函数:
 *   - kprobe/tcp_sendmsg           : 捕获 HTTP 请求发送（读取用户态明文 GET/POST 等）
 *   - kprobe/tcp_recvmsg_locked    : entry probe，保存 sk + msg 上下文
 *   - kretprobe/tcp_recvmsg_locked : return probe，读取 entry 保存的上下文，匹配 HTTP 响应
 *
 * 设计说明: 为什么用 entry+return 配对？
 *   kretprobe 的 PT_REGS_PARM1 是返回值，不是入口参数。
 *   因此必须在 entry kprobe 时保存 struct sock *sk 和 struct msghdr *msg 到 Map，
 *   在 retprobe 时读回，才能正确提取 socket 和 I/O 缓冲区信息。
 *
 * 使用的 BPF Map:
 *   - http_txn_stats  : LRU_HASH，存储进行中的 HTTP 事务（请求→响应配对）
 *   - recvmsg_ctx_map : HASH，key=PID，保存 tcp_recvmsg 的 entry 上下文供 retprobe 使用
 *   - http_debug      : ARRAY，64 槽位的调试计数器，用 dbg_inc(idx) 验证各代码分支是否命中
 *
 * 用户态对应的 Monitor 类: HttpLatencyMonitor
 */

#define __TARGET_ARCH_arm64
#define AF_INET 2
#define AF_INET6 10
// 只读取用户态缓冲区前 64 字节用于 HTTP 方法/状态码识别
// 原因：BPF 栈大小限制（默认 512 字节），不能读太大
#define MAX_HTTP_PAYLOAD 64

#include "vmlinux.h"
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_core_read.h>
#include <bpf/bpf_tracing.h>
#include <bpf/bpf_endian.h>

char LICENSE[] SEC("license") = "GPL";

// =============================================================================
// 数据结构定义
// =============================================================================

/*
 * TCP 连接标识 Key（支持 IPv4/IPv6）
 * IPv4 时 saddr[3]/daddr[3] 存 32 位地址，[0]-[2] 为 0
 * IPv6 时 saddr/daddr 为完整 128 位地址
 */
struct tcp_conn_key {
    __u32 saddr[4];  // 源地址（IPv4 低 32 位有效；IPv6 完整 128 位）
    __u32 daddr[4];  // 目的地址
    __u16 sport;     // 源端口（网络序）
    __u16 dport;     // 目的端口（网络序）
};

/* HTTP 事务 Key —— 与 tcp_conn_key 结构相同 */
struct http_txn_key {
    __u32 saddr[4];
    __u32 daddr[4];
    __u16 sport;
    __u16 dport;
};

/*
 * HTTP 事务记录（存储在 http_txn_stats Map 中）
 * 一次 HTTP 请求→响应周期：
 *   is_request=1 → 请求已发送，等待响应
 *   is_request=0 → 响应已接收，记录完整
 * 用户态读取后可计算 TTFB = recv_ns - send_ns
 */
struct http_txn_record {
    __u64 send_ns;       // HTTP 请求发送时间戳（bpf_ktime_get_ns）
    __u64 recv_ns;       // HTTP 响应首字节到达时间戳
    __u32 req_bytes;     // 请求体字节数（tcp_sendmsg 的 size 参数）
    __u32 resp_bytes;    // 响应体字节数（tcp_recvmsg 的返回值 ret）
    __u16 status_code;   // HTTP 状态码（200/301/404/500 等）
    __u8  is_request;    // 标记：1=仅请求，0=请求+响应完整
    __u8  padding;       // 对齐填充，不使用
};

/*
 * tcp_recvmsg 的 entry→retprobe 配对上下文
 * kretprobe 无法直接拿到入口的参数，需要用 PID 作为中间键保存
 */
struct recvmsg_ctx {
    struct sock *sk;      // TCP socket 指针（用于构造连接 Key）
    struct msghdr *msg;   // 消息头指针（用于读用户态 iov 里的 HTTP 响应明文）
};

// =============================================================================
// BPF Map 定义
// =============================================================================

/*
 * Map: http_txn_stats
 * 类型: BPF_MAP_TYPE_LRU_HASH（最近最少使用淘汰）
 * Key:  struct http_txn_key（TCP 连接 4 元组）
 * Value: struct http_txn_record（HTTP 事务记录）
 * 最大条目数: 8192（同时进行的 HTTP 连接上限）
 * 用途: 存储进行中的 HTTP 请求。tcp_sendmsg 入口创建，
 *       tcp_recvmsg 返回时匹配并补全响应信息。LRU 淘汰保证长时间无响应
 *       的连接不会撑爆内存。
 */
struct {
    __uint(type, BPF_MAP_TYPE_LRU_HASH);
    __uint(max_entries, 8192);
    __type(key, struct http_txn_key);
    __type(value, struct http_txn_record);
} http_txn_stats SEC(".maps");

/*
 * Map: recvmsg_ctx_map
 * 类型: BPF_MAP_TYPE_HASH
 * Key:  __u32 = PID（bpf_get_current_pid_tgid() 高 32 位）
 * Value: struct recvmsg_ctx（sk + msg 指针）
 * 最大条目数: 1024
 * 用途: entry kprobe 保存 tcp_recvmsg 的入口参数，retprobe 时读回。
 *       之所以用 PID 而不是 sk，是因为 entry 和 retprobe 之间可能有
 *       其他 socket 的 recvmsg 穿插，PID 保证是同一个 syscall 上下文。
 *       retprobe 读完后立即 delete，避免残留。
 */
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);
    __type(value, struct recvmsg_ctx);
} recvmsg_ctx_map SEC(".maps");

/*
 * Map: http_self_pid
 * 存放 weaknet-server 自身的 PID，用于排除**主动探测**产生的明文 HTTP 流量。
 *
 * 为什么这里尤为关键：Captive Portal 的受控 oracle 走的就是**明文 HTTP**
 * （门户拦截通常发生在明文层），所以它的请求与响应会被本探针完整识别为
 * "真实业务 HTTP 流量"并写入 http_txn_stats。若不排除：
 *   - passive Cleartext HTTP SLE 被 probe 流量污染
 *   - W1 硬验收"仅开探测时 passive 计数零增长"直接失败
 *
 * 本探针的所有挂点都在**发起 recvmsg/sendmsg 的进程上下文**中

