std::string NetTrafficAnalyzer::generateFlowKey(const FlowRate& flow) {
    std::ostringstream oss;
    oss << flow.src << ":" << flow.sport << "-" << flow.dst << ":" << flow.dport << "/" << flow.proto;
    return oss.str();
}

